using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckBuzkashi.Editor {
public static class BuzAuthoring {
 public const string Folder="TruckBuzkashi",Scene="Assets/TruckBuzkashi/Scenes/TruckBuzkashi.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<BuzMatch>(Folder);m.setup.count=6;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();var grass=SportsEventAuthoring.Mat(Folder,"Buzkashi grass",new Color(.49f,.61f,.32f),.15f);grass.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/GrassAlbedo.png");grass.mainTextureScale=new Vector2(35,40);grass.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/GrassNormal.png"));grass.EnableKeyword("_NORMALMAP");var contact=SportsEventAuthoring.Contact(Folder,"Field contact",.55f,.06f);SportsEventAuthoring.Box("Broad physical grass field",new Vector3(0,-.25f,0),new Vector3(116,.5f,132),grass,contact);var dress=new GameObject("Installed Buzkashi field props").transform;for(int side=-1;side<=1;side+=2){var wall=SportsEventAuthoring.Box("Continuous field boundary side",new Vector3(side*54,.6f,0),new Vector3(.45f,1.2f,122),grass,contact);wall.GetComponent<Renderer>().enabled=false;wall.AddComponent<BuzSolidBarrier>();wall=SportsEventAuthoring.Box("Continuous field end",new Vector3(0,.6f,side*61),new Vector3(108,1.2f,.45f),grass,contact);wall.GetComponent<Renderer>().enabled=false;wall.AddComponent<BuzSolidBarrier>();for(int i=0;i<25;i++){var holder=new GameObject("Installed field barrier").transform;holder.SetParent(dress);holder.position=new Vector3(side*54,0,-58+i*4.8f);holder.rotation=Quaternion.Euler(0,90,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",new Vector3(4.7f,1.2f,.5f),0,true);}for(int i=0;i<22;i++)SportsRallyAuthoring.Prop(dress,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",new Vector3(-50+i*4.8f,0,side*61),new Vector3(4.7f,1.2f,.5f));for(int z=-1;z<=1;z+=2){var root=new GameObject("Hay bale route island").transform;root.SetParent(dress);root.position=new Vector3(side*30,0,z*14);SportsRallyAuthoring.Prop(root,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Pallet Variant.prefab",Vector3.zero,new Vector3(6,1,4));var blocker=root.gameObject.AddComponent<BoxCollider>();blocker.center=new Vector3(0,.5f,0);blocker.size=new Vector3(6,1,4);blocker.sharedMaterial=contact;root.gameObject.AddComponent<BuzSolidBarrier>();}}
 m.trucks=new SportsEventTruck[6];m.identities=new TextMesh[6];for(int i=0;i<6;i++){m.setup.players[i].color=Color.Lerp(i<3?new Color(.1f,.7f,1):new Color(1,.43f,.1f),Color.white,i%3*.14f);m.trucks[i]=SportsEventAuthoring.Truck(m,Folder,"Buzkashi competitor "+i,new Vector3((i%3-1)*11,.55f,i<3?-25:25),i);SportsRallyAuthoring.FitTruck(m.trucks[i]);m.trucks[i].maxSpeed=17;m.trucks[i].steerAngle=36;var impact=m.trucks[i].gameObject.AddComponent<BuzImpact>();impact.slot=i;impact.match=m;m.identities[i]=SportsEventAuthoring.Label("Team identity "+i,m.setup.players[i].name,m.trucks[i].transform.position+Vector3.up*2.5f,.12f,m.setup.players[i].color);m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();}
 var cargo=new GameObject("One authoritative stuffed sheep cargo");cargo.transform.position=new Vector3(0,1.5f,0);m.contacts=cargo.AddComponent<BuzCargoContacts>();m.cargo=cargo.AddComponent<Rigidbody>();m.cargo.mass=3.5f;m.cargo.linearDamping=.16f;m.cargo.angularDamping=.9f;m.cargo.interpolation=RigidbodyInterpolation.Interpolate;m.cargo.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;m.cargo.solverIterations=16;m.cargo.maxDepenetrationVelocity=3;var visual=new GameObject("Actual SheepV5 stuffed cargo").transform;visual.SetParent(cargo.transform,false);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(visual,"Assets/TruckCheeseRolling/Art/Sheep/SheepV5.fbx",new Vector3(3.2f,2.5f,4.8f),-1.25f,true);m.cargoShape=cargo.AddComponent<BoxCollider>();m.cargoShape.size=new Vector3(3.2f,2.5f,4.8f);m.cargoShape.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Stuffed cargo contact",.3f,.08f);var cloth=SportsEventAuthoring.Mat(Folder,"Stuffed fabric stitches",new Color(.27f,.18f,.13f),.1f);for(int i=0;i<9;i++){var stitch=SportsEventAuthoring.Box("Visible plush belly seam stitch",new Vector3(.04f,1.3f,-1.8f+i*.42f),new Vector3(.22f,.035f,.045f),cloth,null,cargo.transform);stitch.transform.localRotation=Quaternion.Euler(0,i%2==0?25:-25,0);}
 m.floppy=new Rigidbody[2];m.floppyOffsets=new Vector3[2];for(int i=0;i<2;i++){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="Soft bounded plush tassel "+i;g.transform.position=cargo.transform.position+new Vector3(i==0?-1.75f:1.75f,.5f,.9f);g.transform.localScale=new Vector3(.5f,.23f,.75f);g.GetComponent<Renderer>().sharedMaterial=SportsEventAuthoring.Mat(Folder,"Soft plush ears",new Color(.88f,.81f,.67f),.1f);var body=g.AddComponent<Rigidbody>();body.mass=.08f;body.angularDamping=2;body.linearDamping=.6f;body.solverIterations=12;m.floppy[i]=body;m.floppyOffsets[i]=g.transform.position-cargo.transform.position;var joint=g.AddComponent<ConfigurableJoint>();joint.connectedBody=m.cargo;joint.xMotion=joint.yMotion=joint.zMotion=ConfigurableJointMotion.Limited;joint.linearLimit=new SoftJointLimit{limit=.18f};joint.angularXMotion=joint.angularYMotion=joint.angularZMotion=ConfigurableJointMotion.Limited;joint.lowAngularXLimit=new SoftJointLimit{limit=-30};joint.highAngularXLimit=new SoftJointLimit{limit=30};joint.angularYLimit=joint.angularZLimit=new SoftJointLimit{limit=25};joint.slerpDrive=new JointDrive{positionSpring=1,positionDamper=.5f,maximumForce=3};joint.rotationDriveMode=RotationDriveMode.Slerp;joint.enableCollision=false;}
 var rope=new GameObject("Visible bounded physical tow rope").AddComponent<LineRenderer>();m.rope=rope;rope.positionCount=7;rope.startWidth=rope.endWidth=.085f;rope.sharedMaterial=SportsEventAuthoring.Mat(Folder,"Tow rope ochre",new Color(.8f,.58f,.2f),.25f);rope.enabled=false;rope.numCapVertices=3;m.corralNames=new TextMesh[2];for(int team=0;team<2;team++){var color=team==0?new Color(.1f,.6f,1):new Color(1,.4f,.07f);var paint=SportsEventAuthoring.Mat(Folder,"Corral paint "+team,color,.1f);float z=team==0?-49:49;for(int e=0;e<4;e++)SportsEventAuthoring.Box("Whole cargo corral outline",e<2?new Vector3(e==0?-12:12,.025f,z):new Vector3(0,.025f,z+(e==2?-9:9)),e<2?new Vector3(.24f,.035f,18):new Vector3(24,.035f,.24f),paint);m.corralNames[team]=SportsEventAuthoring.Label("Home corral "+team,m.teams[team]+"\nHOME CORRAL",new Vector3(0,.05f,z),.35f,color);m.corralNames[team].transform.rotation=Quaternion.Euler(90,-90,0);}
 m.broadcast=SportsEventAuthoring.Camera("Complete Buzkashi broadcast");m.broadcast.Pose(new Vector3(0,2,0),new Vector3(90,65,-5),58,true);m.broadcast.view.orthographic=true;m.framing=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.framing.cameraTarget=m.broadcast.view;m.framing.arenaFit=true;m.framing.arenaBounds=new Bounds(new Vector3(0,2,0),new Vector3(109,7,124));m.framing.topInset=.045f;m.framing.bottomInset=.065f;m.framing.Apply();m.cameras=new[]{m.broadcast.view};for(int i=0;i<32;i++)LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(dress,new Vector3(i%2==0?-70:70,0,-75+i*5),7,i%4!=0,Folder);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);TeamUI(m);InstallLabels(m);BuzNameplateAuthoring.Install(m);SportsEventAuthoring.Save(Folder);Validate();}
 static void TeamUI(BuzMatch m){var menus=m.menus;Array.Resize(ref menus.pages,9);var page=SportsUIAuthoring.Page("Team names",menus.transform,"NAME YOUR TEAMS","Individual truck sources stay assigned to their own participant");menus.pages[8]=page;m.teamInputs=new TMPro.TMP_InputField[2];for(int i=0;i<2;i++)m.teamInputs[i]=SportsUIAuthoring.Name(page.transform,"TEAM "+(i+1),m.teams[i],new Vector2(0,110-i*140));SportsUIAuthoring.Button(page.transform,"BACK","teamback",new Vector2(0,-300));SportsUIAuthoring.Button(menus.pages[0].transform,"TEAM NAMES","teamsetup",new Vector2(0,-268),new Vector2(400,42));menus.teamAText.GetComponentInParent<UnityEngine.UI.Button>(true).interactable=false;menus.teamBText.GetComponentInParent<UnityEngine.UI.Button>(true).interactable=false;page.SetActive(false);}
 public static void InstallLabels(BuzMatch m){var names=m.GetComponent<BuzNameplates>()??m.gameObject.AddComponent<BuzNameplates>();names.match=m;if(names.root!=null)UnityEngine.Object.DestroyImmediate(names.root.gameObject);var g=SportsUIAuthoring.Rect("Projected Buzkashi names",m.menus.transform,Vector2.zero,Vector2.zero);names.root=g.GetComponent<RectTransform>();names.root.anchorMin=Vector2.zero;names.root.anchorMax=Vector2.one;names.root.offsetMin=names.root.offsetMax=Vector2.zero;names.plates=new RectTransform[6];names.captions=new TMPro.TMP_Text[6];for(int i=0;i<6;i++){m.identities[i].GetComponent<Renderer>().enabled=false;var plate=SportsUIAuthoring.Rect("Driver caption "+i,names.root,new Vector2(252,32),Vector2.zero);var rect=plate.GetComponent<RectTransform>();rect.anchorMin=rect.anchorMax=Vector2.zero;plate.AddComponent<UnityEngine.UI.Image>().color=new Color(.01f,.02f,.035f,.8f);plate.GetComponent<UnityEngine.UI.Image>().raycastTarget=false;var text=SportsUIAuthoring.Text("Name",plate.transform,m.setup.players[i].name,new Vector2(242,30),Vector2.zero,24);text.fontSizeMin=22;text.fontSizeMax=24;text.textWrappingMode=TMPro.TextWrappingModes.NoWrap;text.overflowMode=TMPro.TextOverflowModes.Ellipsis;names.plates[i]=rect;names.captions[i]=text;plate.SetActive(false);}g.SetActive(false);EditorUtility.SetDirty(m);}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<BuzMatch>();if(m==null||m.trucks.Length!=6||m.floppy.Length!=2||m.cargoShape==null||m.contacts==null||m.teamInputs.Length!=2||m.rope.positionCount!=7||m.GetComponent<BuzNameplates>()==null)throw new Exception("Buzkashi scene references missing");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Buzkashi listener count");Debug.Log("BUZ_SAVED_VALIDATED six NWH trucks one constrained floppy cargo");}
}
